e,'/pieces/plaquette-de-frein-402/renault-140/clio-ii-140003/1-5-dci-16108.html'),(402,30936,4,false,'/pieces/plaquette-de-frein-402/renault-140/clio-ii-140003/1-5-dci-campus-30936.html'),(402,19341,5,false,'/pieces/plaquette-de-frein-402/peugeot-128/307-128035/1-6-hdi-19341.html'),(402,17989,6,false,'/pieces/plaquette-de-frein-402/peugeot-128/307-128035/1-6-hdi-17989.html'),(402,15903,7,false,'/pieces/plaquette-de-frein-402/peugeot-128/307-128035/2-0-hdi-15903.html'),(402,18400,8,false,'/pieces/plaquette-de-frein-402/audi-22/a4-iii-22042/1-9-tdi-18400.html'),(402,26547,9,false,'/pieces/plaquette-de-frein-402/audi-22/a4-iii-22042/2-0-tdi-26547.html'),(402,27326,10,false,'/pieces/plaquette-de-frein-402/audi-22/a4-iii-22042/2-0-tdi-27326.html'),(402,8456,11,false,'/pieces/plaquette-de-frein-402/volkswagen-173/golf-iv-173039/1-9-tdi-8456.html'),(402,8461,12,false,'/pieces/plaquette-de-frein-402/volkswagen-173/golf-iv-173039/1-9-tdi-8461.html'),(402,13100,13,true,'/pieces/plaquette-de-frein-402/volkswagen-173/golf-iv-173039/1-9-tdi-13100.html'),(402,58963,14,true,'/pieces/plaquette-de-frein-402/bmw-33/serie-1-e81-33017/2-0-116-d-58963.html'),(402,31672,15,true,'/pieces/plaquette-de-frein-402/bmw-33/serie-1-e81-33017/2-0-116-d-31672.html'),(402,32172,16,true,'/pieces/plaquette-de-frein-402/bmw-33/serie-1-e81-33017/2-0-118-d-32172.html'),(402,58791,17,true,'/pieces/plaquette-de-frein-402/honda-74/civic-ix-74048/1-6-i-dtec-58791.html')),
rel as (select c.pg_id,c.type_id,r.rtp_piece_id from cibles c join pieces_relation_type r on r.rtp_pg_id=c.pg_id and r.rtp_type_id=c.type_id group by 1,2,3),
vend as (select rel.pg_id,rel.type_id,rel.rtp_piece_id,
  bool_or(pp.pri_dispo in ('1','2','3') and coalesce(pp.pricing_state,'')<>'FROZEN' and p.piece_display is true and pp.pri_vente_ttc_n>0) as vendable,
  bool_or(p.piece_display is true) as affichee
  from rel join pieces p on p.piece_id=rel.rtp_piece_id left join pieces_price pp on pp.pri_piece_id=rel.rtp_piece_id::text group by 1,2,3)
select c.pg_id,c.type_id,c.rang,c.repliee,
 (select count(*) from rel where rel.pg_id=c.pg_id and rel.type_id=c.type_id) as pieces_liees,
 (select count(*) filter (where affichee) from vend v where v.pg_id=c.pg_id and v.type_id=c.type_id) as pieces_affichees,
 (select count(*) filter (where vendable) from vend v where v.pg_id=c.pg_id and v.type_id=c.type_id) as pieces_vendables,
 (select t.type_display from auto_type t where t.type_id=c.type_id::text limit 1) as type_display,
 (select count(*) from __sitemap_p_link s where s.map_pg_id=c.pg_id and s.map_type_id=c.type_id) as sitemap_lignes,
 (select max(s.map_has_item) from __sitemap_p_link s where s.map_pg_id=c.pg_id and s.map_type_id=c.type_id) as sitemap_has_item
from cibles c order by c.pg_id,c.rang;
